// emit/mcs-common/relations.mjs — service/<resource>LookupService.ts, ONE per distinct
// relation.resource across the whole spec (two fields referencing "Policy" share one
// generated file - dedup here, not per-page). Same graceful-degradation pattern proven in
// design-lab/revenue-sharing-algorithm: no base URL env var set -> [] + one console.warn.
import fs from 'node:fs';
import path from 'node:path';
import { buildResourceModel, listPages } from './resourceModel.mjs';
import { toPascalCase, toCamelCase, toKebabCase } from './naming.mjs';

const BANNER = '// GENERATED by fe-gen emit mcs-common - DO NOT EDIT. Re-run `fe-gen emit` instead.';

/** Parse `"GET /policy?q={query}"` -> { pathNoQuery: '/policy', queryParam: 'q' }.
 * queryParam is whichever query-string key's value is the literal `{query}` placeholder
 * (falls back to 'q' if the spec didn't declare one) - so a spec that says `?search=
 * {query}` actually gets `?search=` in the generated fetch, not a hardcoded `?q=`. */
function parseSearchEndpoint(searchEndpoint, resource) {
  const m = /^([A-Z]+)\s+(.+)$/.exec(searchEndpoint ?? '');
  const pathTemplate = m ? m[2] : `/${toCamelCase(resource)}?q={query}`;
  const [pathNoQuery, queryStr] = pathTemplate.split('?');
  let queryParam = 'q';
  if (queryStr) {
    for (const [k, v] of new URLSearchParams(queryStr)) {
      if (v === '{query}') { queryParam = k; break; }
    }
  }
  return { pathNoQuery, queryParam };
}

function lookupServiceFile(resource, { searchEndpoint, labelField, valueField }) {
  const Resource = toPascalCase(resource);
  const envVar = `REACT_APP_${toKebabCase(resource).toUpperCase().replace(/-/g, '_')}_API_BASE_URL`;
  const { pathNoQuery, queryParam } = parseSearchEndpoint(searchEndpoint, resource);
  const valueKey = JSON.stringify(valueField ?? 'id');
  const labelKey = JSON.stringify(labelField ?? 'name');
  return `${BANNER}
/**
 * Lookup service for the "${resource}" relation - backs RefAutocompleteField's
 * search-and-select (never a manually-typed id). Path/query-param/label-field/value-field
 * come from the fe-spec's field.relation config (see fe-spec.schema.json $defs.fieldRelation).
 * TODO: CUSTOMIZE — confirm these against the real endpoint once a Policy Management-style
 * service exists for this resource; until ${envVar} is set this always resolves to an
 * empty list (no fabricated URL is called), so generation stays deterministic even for a
 * not-yet-built backend.
 */

export interface ${Resource}Option {
  id: string;
  name: string;
  href?: string;
}

const BASE_URL = process.env.${envVar};

let warned = false;

export async function search${Resource}(query: string): Promise<${Resource}Option[]> {
  if (!BASE_URL) {
    if (!warned) {
      // eslint-disable-next-line no-console
      console.warn('[${toCamelCase(resource)}LookupService] ${envVar} is not set - "${resource}" autocomplete will show no options until a real lookup service is wired up.');
      warned = true;
    }
    return [];
  }
  try {
    const url = \`\${BASE_URL}${pathNoQuery}?${queryParam}=\${encodeURIComponent(query)}&limit=20\`;
    const res = await fetch(url);
    if (!res.ok) return [];
    const data = await res.json();
    if (!Array.isArray(data)) return [];
    return data.map((d: any) => ({ id: d[${valueKey}], name: d[${labelKey}] ?? d[${valueKey}], href: d.href }));
  } catch {
    return [];
  }
}
`;
}

export function emitRelations(feir, appDir) {
  const resources = new Map(); // resource -> {searchEndpoint, labelField, valueField} (first occurrence wins)
  for (const page of listPages(feir)) {
    const model = buildResourceModel(page);
    for (const f of model.relationFields) {
      if (!resources.has(f.relation.resource)) {
        resources.set(f.relation.resource, {
          searchEndpoint: f.relation.searchEndpoint,
          labelField: f.relation.labelField,
          valueField: f.relation.valueField,
        });
      }
    }
  }
  const written = [];
  for (const [resource, config] of resources) {
    const rel = `src/service/${toCamelCase(resource)}LookupService.ts`;
    const abs = path.join(appDir, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, lookupServiceFile(resource, config), 'utf8');
    written.push(rel);
  }
  return { written, summary: `relations: ${resources.size} lookup service(s)` };
}
